using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using HotelTogether;
public static class HotelMigrationBuilder {
 const string Root="Assets/HotelTogether/";
 [MenuItem("HotelTogether/Rebuild migrated scene")]
 public static void Build(){
  AssetDatabase.Refresh();var data=JsonUtility.FromJson<MigrationData>(File.ReadAllText(Root+"Migration.json"));var model=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Models/HotelScene.glb");if(!model)throw new Exception("Hotel GLB is not imported yet");
  var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var imported=(GameObject)PrefabUtility.InstantiatePrefab(model);imported.name="Hotel architecture and furnishings";PrefabUtility.UnpackPrefabInstance(imported,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var all=imported.GetComponentsInChildren<Transform>(true);
  var physicsRoot=new GameObject("Architecture collision");int colliderCount=0;foreach(var b in data.colliders){var go=new GameObject("Structure collision "+colliderCount++);go.transform.SetParent(physicsRoot.transform);go.transform.SetPositionAndRotation(Coordinates.V(b.position),Coordinates.Q(b.rotation));AddShapes(go,b);}
  foreach(var p in data.props){var t=all.FirstOrDefault(n=>n.name==p.id);if(!t)throw new Exception("Missing scene object "+p.id);var o=t.gameObject.AddComponent<HotelItem>();o.displayName=p.name;o.kind=p.kind;o.sourceModel=p.file;o.dimensions=Coordinates.Size(p.size);o.home=t.position;o.homeRotation=t.rotation;AddShapes(t.gameObject,p.body);
   if(p.body.mass>0){var rb=t.gameObject.AddComponent<Rigidbody>();rb.mass=p.body.mass;rb.interpolation=RigidbodyInterpolation.Interpolate;rb.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;rb.solverIterations=12;rb.linearDamping=.35f;rb.angularDamping=.65f;}
   if(p.kind=="door"){o.door=p.door;o.leaves=p.door.leaves.Select(l=>all.First(n=>n.name==l.id)).ToArray();for(int i=0;i<o.leaves.Length;i++){var leaf=o.leaves[i].gameObject;leaf.transform.SetParent(t,true);AddShapes(leaf,p.door.leaves[i].body);leaf.AddComponent<DoorLeaf>().owner=o;}var proxy=t.gameObject.AddComponent<BoxCollider>();proxy.size=new Vector3(p.door.w,p.door.height,.10f);proxy.isTrigger=true;}
   if(p.kind=="lamp"){var light=new GameObject("Warm lamp light").AddComponent<Light>();light.transform.SetParent(t,false);light.type=LightType.Point;light.color=new Color(1,.83f,.6f);light.range=3;light.intensity=2;light.shadows=LightShadows.None;o.lamp=light;}
   if(p.file=="DiningTableRound"){var c=t.gameObject.AddComponent<BoxCollider>();c.size=new Vector3(o.dimensions.x,.08f,o.dimensions.z);c.center=new Vector3(0,o.dimensions.y/2-.04f,0);}
  }
  HotelLobbyProportions.ApplyToScene();
  foreach(var r in imported.GetComponentsInChildren<Renderer>()){var item=r.GetComponentInParent<HotelItem>();if(!r.GetComponentInParent<Rigidbody>()&&(item==null||!(item.kind=="door"||item.kind=="pickup"||item.kind=="mop"||item.kind=="cart")))GameObjectUtility.SetStaticEditorFlags(r.gameObject,StaticEditorFlags.BatchingStatic);}
  Directory.CreateDirectory(Root+"Prefabs");foreach(var o in imported.GetComponentsInChildren<HotelItem>())PrefabUtility.SaveAsPrefabAsset(o.gameObject,Root+"Prefabs/"+o.gameObject.name+".prefab");
  var player=new GameObject("Player");player.layer=8;player.transform.position=new Vector3(0,.025f,5.8f);player.transform.rotation=Quaternion.Euler(0,180,0);var cc=player.AddComponent<CharacterController>();cc.height=1.7f;cc.radius=.28f;cc.center=new Vector3(0,.85f,0);cc.stepOffset=.25f;cc.skinWidth=.025f;var camera=new GameObject("Player camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.SetParent(player.transform,false);camera.transform.localPosition=Vector3.up*1.62f;camera.fieldOfView=67;camera.nearClipPlane=.08f;camera.farClipPlane=100;camera.backgroundColor=new Color(.67f,.79f,.83f);camera.clearFlags=CameraClearFlags.SolidColor;camera.gameObject.AddComponent<AudioListener>();camera.GetUniversalAdditionalCameraData().renderPostProcessing=true;player.AddComponent<HotelPlayer>().view=camera;Physics.IgnoreLayerCollision(8,9,true);
  var sun=new GameObject("Warm daylight").AddComponent<Light>();sun.type=LightType.Directional;sun.color=new Color(1,.9f,.75f);sun.intensity=1.8f;sun.transform.rotation=Quaternion.Euler(48,-145,0);sun.shadows=LightShadows.Soft;RenderSettings.sun=sun;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.78f,.74f,.65f);RenderSettings.ambientEquatorColor=new Color(.52f,.49f,.42f);RenderSettings.ambientGroundColor=new Color(.28f,.25f,.21f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.Linear;RenderSettings.fogColor=camera.backgroundColor;RenderSettings.fogStartDistance=45;RenderSettings.fogEndDistance=85;
  foreach(var pos in new[]{new Vector3(0,6.8f,1),new Vector3(-6,3.4f,-3),new Vector3(6,3.4f,3),new Vector3(0,3.8f,-5)}){var l=new GameObject("Lobby warm fill").AddComponent<Light>();l.type=LightType.Point;l.transform.position=pos;l.range=10;l.color=new Color(1,.78f,.48f);l.intensity=3;l.shadows=LightShadows.None;}
  var probe=new GameObject("Lobby reflection probe").AddComponent<ReflectionProbe>();probe.transform.position=new Vector3(0,3,0);probe.size=new Vector3(18,8,14);probe.resolution=128;probe.mode=ReflectionProbeMode.Realtime;probe.refreshMode=ReflectionProbeRefreshMode.OnAwake;probe.intensity=.45f;probe.boxProjection=true;
  var volume=new GameObject("Warm atmosphere").AddComponent<Volume>();volume.isGlobal=true;var profile=ScriptableObject.CreateInstance<VolumeProfile>();profile.Add<Tonemapping>().mode.Override(TonemappingMode.Neutral);profile.Add<Bloom>().intensity.Override(.12f);Directory.CreateDirectory(Root+"Settings");AssetDatabase.DeleteAsset(Root+"Settings/Atmosphere.asset");AssetDatabase.CreateAsset(profile,Root+"Settings/Atmosphere.asset");volume.sharedProfile=profile;
  Directory.CreateDirectory(Root+"Scenes");EditorSceneManager.SaveScene(scene,Root+"Scenes/HotelLobby.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene(Root+"Scenes/HotelLobby.unity",true)};
  PlayerSettings.productName="HotelTogether";PlayerSettings.companyName="HotelTogether";PlayerSettings.defaultScreenWidth=1280;PlayerSettings.defaultScreenHeight=720;PlayerSettings.fullScreenMode=FullScreenMode.Windowed;PlayerSettings.runInBackground=true;QualitySettings.vSyncCount=1;
  HotelGlassTuning.Apply();HotelLobbyArtDirection.Apply();HotelUpperFloors.Apply();AssetDatabase.SaveAssets();SceneView.FrameLastActiveSceneView();Debug.Log("HOTEL_MIGRATION_BUILT props="+data.props.Length+" structures="+colliderCount);
 }
 static void AddShapes(GameObject go,BodyData body){int i=0;foreach(var s in body.shapes??Array.Empty<ShapeData>()){var child=new GameObject("Collision "+i++);child.transform.SetParent(go.transform,false);child.transform.localPosition=Coordinates.V(s.offset);child.transform.localRotation=Coordinates.Q(s.rotation);if(s.type==4&&s.size.Length==3){var c=child.AddComponent<BoxCollider>();c.size=Coordinates.Size(s.size)*2;}else if(s.type==1){child.AddComponent<SphereCollider>().radius=s.radius;}else UnityEngine.Object.DestroyImmediate(child);}}
 public static void BuildMac(){var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Root+"Scenes/HotelLobby.unity"},locationPathName=Path.GetFullPath(Path.Combine(Application.dataPath,"../../HotelTogether-Mac/HotelTogether.app")),target=BuildTarget.StandaloneOSX,options=BuildOptions.None});if(result.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Build failed "+result.summary.result);}
}
